import{_ as i,a0 as l,w as n,s,I as p,x as r,a1 as a,A as d,ao as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"一些不起眼但非常有用的 Vim 命令 | LCTT x X-CMD","titleTemplate":false,"description":"一些不起眼但非常有用的 Vim 命令 | LCTT (201501) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"一些不起眼但非常有用的 Vim 命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"一些不起眼但非常有用的 Vim 命令 | LCTT (201501) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201501/20141115 What are some obscure but useful Vim commands","title":"一些不起眼但非常有用的 Vim 命令","tag":"201501","desc":""},"relativePath":"201501/20141115 What are some obscure but useful Vim commands.md","filePath":"[post].md"}'),m={name:"201501/20141115 What are some obscure but useful Vim commands.md"};function c(f,e,h,u,b,V){const o=l("Link");return n(),s("div",null,[e[22]||(e[22]=p("h1",{id:"一些不起眼但非常有用的-vim-命令",tabindex:"-1"},[r("一些不起眼但非常有用的 Vim 命令 "),p("a",{class:"header-anchor",href:"#一些不起眼但非常有用的-vim-命令","aria-label":"Permalink to “一些不起眼但非常有用的 Vim 命令”"},"​")],-1)),p("p",null,[e[1]||(e[1]=r("如果我的",-1)),a(o,{href:"http://xmodulo.com/turn-vim-full-fledged-ide.html"},{default:d(()=>[...e[0]||(e[0]=[r("關於這個話題的最新帖子",-1)])]),_:1}),e[2]||(e[2]=r("沒有提醒到你的話，那我明確地説，我是一個 Vim 的粉絲。所以在你們中的某些人向我扔石頭之前，我先向你們展示一系列“鮮為人知的 Vim 命令”。我的意思是，一些你可能以前沒有碰到過的命令，但可能對你來説很有用。作為第二免責聲明，我不知道哪些命令是你可能知道的，以及哪些是對你來説有用的。因此這些命令實際上是一些相對少見，但很可能很有用的 Vim 命令。",-1))]),e[23]||(e[23]=t(`<h3 id="保存文件並退出" tabindex="-1">保存文件並退出 <a class="header-anchor" href="#保存文件並退出" aria-label="Permalink to “保存文件並退出”">​</a></h3><p>説起來有些慚愧，我也是最近才學到這個命令</p><pre><code>:x
</code></pre><p>和下面的命令是等價的：</p><pre><code>:wq
</code></pre><p>都是保存當前文件並退出。</p><p>（譯者注：這兩個命令實際上並不完全等價，當文件被修改時兩個命令時相同的。但如果未被修改，使用 <code>:x</code> 不會更改文件的修改時間，而使用 <code>:wq</code> 會改變文件的修改時間。）</p><h3 id="基本計算器" tabindex="-1">基本計算器 <a class="header-anchor" href="#基本計算器" aria-label="Permalink to “基本計算器”">​</a></h3><p>在插入模式下，你可以使用 Ctrl+r 鍵然後輸入 <code>=</code>，再輸入一個簡單的算式。按 Enter 鍵，計算結果就會插入到文件中。例如，嘗試輸入：</p><pre><code>Ctrl+r &#39;=2+2&#39; ENTER
</code></pre><p><img src="https://farm8.staticflickr.com/7486/15543918097_fbcf33ee6b.jpg" alt=""></p><p>然後計算結果“4 ”會被插入到文件中。</p><h3 id="查找重複的連續的單詞" tabindex="-1">查找重複的連續的單詞 <a class="header-anchor" href="#查找重複的連續的單詞" aria-label="Permalink to “查找重複的連續的單詞”">​</a></h3><p>當你很快地打字時，很有可能會連續輸入同一個單詞兩次，就像 this this。這種錯誤可能騙過任何一個人，即使是你自己重新閲讀一遍也不可避免。幸運的是，有一個簡單的正則表達式可以用來預防這個錯誤。使用搜索命令（默認時 <code>/</code>）然後輸入：</p><pre><code>\\(\\&lt;\\w\\+\\&gt;\\)\\_s*\\1
</code></pre><p>這會顯示所有重複的單詞。要達到最好的效果，不要忘記把下面的命令：</p><pre><code>set hlsearch
</code></pre><p>放到你的 .vimrc 文件中高亮所有的匹配。</p><p><img src="https://farm8.staticflickr.com/7531/15730650082_c2764857e2.jpg" alt=""></p><h3 id="縮寫" tabindex="-1">縮寫 <a class="header-anchor" href="#縮寫" aria-label="Permalink to “縮寫”">​</a></h3><p>一個很可能是最令人印象深刻的竅門是你可以在 Vim 中定義縮寫，它可以實時地把你輸入的東西替換為另外的東西。語法格式如下：</p><pre><code>:ab [縮寫] [要替換的文字]
</code></pre><p>一個通用的例子是：</p><pre><code>:ab asap as soon as possible
</code></pre><p>會把你輸入的 “asap” 替換為 “as soon as possible”。</p><h3 id="在你忘記用-root-方式打開文件時的文件保存" tabindex="-1">在你忘記用 root 方式打開文件時的文件保存 <a class="header-anchor" href="#在你忘記用-root-方式打開文件時的文件保存" aria-label="Permalink to “在你忘記用 root 方式打開文件時的文件保存”">​</a></h3><p>這可能是一個在論壇中一直受歡迎的命令。每當你打開一個你沒有寫入權限的文件（比如系統配置文件）並做了一些修改，Vim 無法通過普通的 “:w” 命令來保存。</p><p>你不需要重新以 root 方式打開文件再進行修改，只需要運行：</p><pre><code>:w !sudo tee %
</code></pre><p>這會直接以 root 方式保存。</p><h3 id="實時加密文本" tabindex="-1">實時加密文本 <a class="header-anchor" href="#實時加密文本" aria-label="Permalink to “實時加密文本”">​</a></h3>`,31)),p("p",null,[e[4]||(e[4]=r("如果你不想讓別人看懂你的屏幕上的內容，你可以使用一個內置的選項，通過下面的命令使用 ",-1)),a(o,{href:"https://en.wikipedia.org/wiki/ROT13"},{default:d(()=>[...e[3]||(e[3]=[r("ROT13",-1)])]),_:1}),e[5]||(e[5]=r(" 來對文本進行編碼：",-1))]),e[24]||(e[24]=t(`<pre><code>ggVGg?
</code></pre><p><img src="https://farm8.staticflickr.com/7487/15727174681_7773a97ea2.jpg" alt=""></p><p><code>gg</code> 把光標移動到 Vim 緩衝區的第一行，<code>V</code> 進入可視模式，<code>G</code> 把光標移動到緩衝區的最後一行。因此，<code>ggVG</code> 使可視模式覆蓋這個當前緩衝區。最後 <code>g?</code> 使用 ROT13 對整個區域進行編碼。</p><p>注意它可以被映射到一個最常使用的鍵。它對字母符號也可以很好地工作。要對它進行撤銷，最好的方法就是使用撤銷命令：<code>u</code>。</p><p>###自動補全 ###</p><p>這是另外一個令我感到慚愧的功能，但我發現周圍很多人並不知道。Vim 默認有自動補全的功能。的確這個功能是很基本的，並且可以通過插件來增強，但它也很有幫助。方法很簡單。Vim 嘗試通過已經輸入的單詞來預測單詞的結尾。比如當你在同一個文件中第二次輸入 “compiler” 時，僅僅輸入 “com” 然後保持在插入模式，按 Ctrl+n 鍵就可以看到 Vim 為你補全了單詞。很簡單，但也很有用。</p><h3 id="比較兩個文件的不同" tabindex="-1">比較兩個文件的不同 <a class="header-anchor" href="#比較兩個文件的不同" aria-label="Permalink to “比較兩個文件的不同”">​</a></h3><p>你們中的大多數很可能都知道 vimdiff 命令，它可以使用分離模式打開 Vim 並比較兩個文件的不同。語法如下：</p><pre><code>$ vimdiff [文件1] [文件2]
</code></pre><p>但同樣的結果也可以通過下面的 Vim 命令來獲得：</p><pre><code>:diffthis
</code></pre><p>首先在 Vim 中打開原始文件。然後使用分離模式帶來第二個文件：</p><pre><code>:vsp [文件2]
</code></pre><p>最後在第一個緩衝區裏輸入：</p><pre><code>:diffthis
</code></pre><p>通過 Ctrl+w 來切換緩衝區並再次輸入：</p><pre><code>:diffthis
</code></pre><p>這樣兩個文件中不同的部分就會被高亮。</p><p>（譯者注：可以直接在一個緩衝區裏使用命令 <code>:windo diffthis</code>，而不用輸入 <code>:diffthis</code> 兩次）</p><p>要停止比較，使用：</p><pre><code>:diffoff
</code></pre><h3 id="按時間回退文件" tabindex="-1">按時間回退文件 <a class="header-anchor" href="#按時間回退文件" aria-label="Permalink to “按時間回退文件”">​</a></h3><p>Vim 會記錄文件的更改，你很容易可以回退到之前某個時間。該命令是相當直觀的。比如：</p><pre><code>:earlier 1m
</code></pre><p>會把文件回退到 1 分鐘以前的狀態。</p><p>注意，你可以使用下面的命令進行相反的轉換：</p><pre><code>:later
</code></pre><h3 id="刪除標記內部的文字" tabindex="-1">刪除標記內部的文字 <a class="header-anchor" href="#刪除標記內部的文字" aria-label="Permalink to “刪除標記內部的文字”">​</a></h3><p>當我開始使用 Vim 時，一件我總是想很方便做的事情是如何輕鬆的刪除方括號或圓括號裏的內容。轉到開始的標記，然後使用下面的語法：</p><pre><code>di[標記]
</code></pre><p>比如，把光標放在開始的圓括號上，使用下面的命令來刪除圓括號內的文字：</p><pre><code>di(
</code></pre><p>如果是方括號或者是引號，則使用：</p><pre><code>di{
</code></pre><p>和：</p><pre><code>di&quot;
</code></pre><h3 id="刪除指定標記前的內容" tabindex="-1">刪除指定標記前的內容 <a class="header-anchor" href="#刪除指定標記前的內容" aria-label="Permalink to “刪除指定標記前的內容”">​</a></h3><p>和刪除標記內部有些相似，但目的不同。命令如下：</p><pre><code>dt[標記]
</code></pre><p>會刪除所有光標和標記之間的內容（保持標記不動），如果在同一行有這個標記的話。例如</p><pre><code>dt.
</code></pre><p>會刪除至句子的末尾，但保持 ‘.’ 不動。</p><h3 id="把-vim-變為十六進制編輯器" tabindex="-1">把 Vim 變為十六進制編輯器 <a class="header-anchor" href="#把-vim-變為十六進制編輯器" aria-label="Permalink to “把 Vim 變為十六進制編輯器”">​</a></h3><p>這不是我最喜歡的竅門，但有時會很有趣。你可以把 Vim 和 xxd 功能連起來來把文件轉換為十六進制模式。命令如下：</p><pre><code>:%!xxd
</code></pre><p><img src="https://farm6.staticflickr.com/5607/15109142674_e99466f2db_z.jpg" alt=""></p><p>類似的，你可以通過下面的命令恢復原來的狀態：</p><pre><code>:%!xxd -r
</code></pre><h3 id="把光標下的文字置於屏幕中央" tabindex="-1">把光標下的文字置於屏幕中央 <a class="header-anchor" href="#把光標下的文字置於屏幕中央" aria-label="Permalink to “把光標下的文字置於屏幕中央”">​</a></h3><p>我們所要做的事情如標題所示。如果你想強制滾動屏幕來把光標下的文字置於屏幕的中央，在可視模式中使用命令（譯者注：在普通模式中也可以）：</p><pre><code>zz
</code></pre><h3 id="跳到上一個-下一個位置" tabindex="-1">跳到上一個／下一個位置 <a class="header-anchor" href="#跳到上一個-下一個位置" aria-label="Permalink to “跳到上一個／下一個位置”">​</a></h3><p>當你編輯一個很大的文件時，經常要做的事是在某處進行修改，然後跳到另外一處。如果你想跳回之前修改的地方，使用命令：</p><pre><code>Ctrl+o
</code></pre><p>來回到之前修改的地方</p><p>類似的：</p><pre><code>Ctrl+i
</code></pre><p>會回退上面的跳動。</p><h3 id="把當前文件轉化為網頁" tabindex="-1">把當前文件轉化為網頁 <a class="header-anchor" href="#把當前文件轉化為網頁" aria-label="Permalink to “把當前文件轉化為網頁”">​</a></h3><p>這會生成一個 HTML 文件來顯示文本，並在分開的窗口顯示源代碼：</p><pre><code>:%TOhtml
</code></pre><p>（譯者注：原文是 <code>:%Tohtml</code>，但在我的電腦上是 <code>:%TOhtml</code>）</p><p><img src="https://farm8.staticflickr.com/7550/15727174701_c405f85a84_z.jpg" alt=""></p><p>很基本但很不錯。</p>`,64)),p("p",null,[e[7]||(e[7]=r("總的來説，這一系列命令是在我讀了許多論壇主題和 ",-1)),a(o,{href:"http://vim.wikia.com/wiki/Vim_Tips_Wiki"},{default:d(()=>[...e[6]||(e[6]=[r("Vim Tips wiki",-1)])]),_:1}),e[8]||(e[8]=r("（如果你想學習更多關於編輯器的知識，我非常推薦這篇文章） 之後收集起來的。",-1))]),e[25]||(e[25]=p("p",null,"如果你還知道哪些非常有用但你認為大多數人並不知道的命令，可以隨意在評論中分享出來。就像引言中所説的，一個“鮮為人知但很有用的”命令也許只是你自己的看法，但分享出來總是好的。",-1)),e[26]||(e[26]=p("hr",null,null,-1)),p("p",null,[e[10]||(e[10]=r("via: ",-1)),a(o,{href:"http://xmodulo.com/useful-vim-commands.html"},{default:d(()=>[...e[9]||(e[9]=[r("http://xmodulo.com/useful-vim-commands.html",-1)])]),_:1})]),p("p",null,[e[14]||(e[14]=r("作者：",-1)),a(o,{href:"http://xmodulo.com/author/adrien"},{default:d(()=>[...e[11]||(e[11]=[r("Adrien Brochard",-1)])]),_:1}),e[15]||(e[15]=r(" 譯者：",-1)),a(o,{href:"https://github.com/wangjiezhe"},{default:d(()=>[...e[12]||(e[12]=[r("wangjiezhe",-1)])]),_:1}),e[16]||(e[16]=r(" 校對：",-1)),a(o,{href:"https://github.com/wxy"},{default:d(()=>[...e[13]||(e[13]=[r("wxy",-1)])]),_:1})]),p("p",null,[e[19]||(e[19]=r("本文由 ",-1)),a(o,{href:"https://github.com/LCTT/TranslateProject"},{default:d(()=>[...e[17]||(e[17]=[r("LCTT",-1)])]),_:1}),e[20]||(e[20]=r(" 原創翻譯，",-1)),a(o,{href:"http://linux.cn/"},{default:d(()=>[...e[18]||(e[18]=[r("Linux中國",-1)])]),_:1}),e[21]||(e[21]=r(" 榮譽推出",-1))])])}const k=i(m,[["render",c]]);export{g as __pageData,k as default};
